) AS v(country_code, subdivision_code, name, name_normalized, source, is_free_entry_origin)
WHERE NOT EXISTS (
  SELECT 1 FROM public.ref_cities c
  WHERE c.country_code = v.country_code
    AND c.name_normalized = v.name_normalized
    AND c.subdivision_code IS NOT DISTINCT FROM v.subdivision_code
);

